module.exports = "<ion-header class=\"interior-header\" dir=\"rtl\">\n  \n  <app-page-header titleKey=\"pageHeader.common/doers/doers\" fallback=\"/\">\n<div page-actions><button type=\"button\" class=\"action-btn ghost\" (click)=\"showSearchbar = !showSearchbar\" title=\"جستجو\">\r\n        <ion-icon name=\"search-outline\"></ion-icon>\r\n      </button>\n</div>\n\n<div class=\"header-search-bar\" *ngIf=\"showSearchbar\">\r\n    <div class=\"search-input-wrap\">\r\n      <ion-icon name=\"search-outline\"></ion-icon>\r\n      <input type=\"search\" [(ngModel)]=\"queryText\" placeholder=\"جستجوی مرکز یا شهر...\" (keyup.enter)=\"search()\" autofocus />\r\n      <button type=\"button\" class=\"action-btn primary\" (click)=\"search()\">جستجو</button>\r\n      <button type=\"button\" class=\"action-btn ghost\" (click)=\"onCancel()\">انصراف</button>\r\n    </div>\r\n  </div>\n  </app-page-header>\n</ion-header>\r\n\r\n<ion-content class=\"common-page-content\" dir=\"rtl\">\r\n  <ion-refresher slot=\"fixed\" (ionRefresh)=\"doRefresh($event)\">\r\n    <ion-refresher-content></ion-refresher-content>\r\n  </ion-refresher>\r\n\r\n  <div class=\"common-page-wrapper\">\r\n    <div class=\"backdrop-glows\" aria-hidden=\"true\">\r\n      <div class=\"glow-orb glow-purple\"></div>\r\n      <div class=\"glow-orb glow-amber\"></div>\r\n      <div class=\"glow-orb glow-emerald\"></div>\r\n    </div>\r\n\r\n    <!-- Playful Floating Icons -->\r\n    <span class=\"floating-decor pencil\" aria-hidden=\"true\">🏫</span>\r\n    <span class=\"floating-decor star\" aria-hidden=\"true\">✦</span>\r\n    <span class=\"floating-decor book\" aria-hidden=\"true\">📍</span>\r\n    <span class=\"floating-decor sparkle\" aria-hidden=\"true\">✨</span>\r\n\r\n    <div class=\"content-page-card\">\r\n      <div class=\"content-page-header\">\r\n        <div class=\"header-badge\">\r\n          <span class=\"sparkle-icon\">✦</span>\r\n          <span>شبکه مراکز آموزشی همکار</span>\r\n        </div>\r\n        <h1>مراکز همکار و نمایندگان اول آموز</h1>\r\n        <p>\r\n          آموزشگاه‌ها، موسسات توانمندسازی نوآموزان و نمایندگی‌های معتبر ارائه‌دهنده خدمات و ملزومات اول آموز در سراسر کشور\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"faq-loading-state\" *ngIf=\"isLoadingList\">\r\n        <ion-spinner name=\"bubbles\" color=\"primary\"></ion-spinner>\r\n        <span>در حال بارگذاری مراکز همکار...</span>\r\n      </div>\r\n\r\n      <div class=\"doers-cards-grid\" *ngIf=\"!isLoadingList && doers.length > 0\">\r\n        <div class=\"doer-card\" *ngFor=\"let doer of doers; let i = index\">\r\n          <div class=\"doer-card-top\">\r\n            <div class=\"doer-avatar-wrap\">\r\n              <img [src]=\"doer.image === 'Default-Doer' ? 'assets/images/Default-Doer.png' : doer.image\" [alt]=\"doer.brand\" />\r\n            </div>\r\n\r\n            <div class=\"doer-rating\">\r\n              <ion-icon\r\n                *ngFor=\"let item of onMakeArray(getPoint(doer.point))\"\r\n                name=\"star\"\r\n                class=\"star-filled\"\r\n              ></ion-icon>\r\n            </div>\r\n          </div>\r\n\r\n          <h3 class=\"doer-name\">{{ doer.name }} {{ doer.family }}</h3>\r\n          <span class=\"doer-brand-chip\" *ngIf=\"doer.brand\">{{ doer.brand }}</span>\r\n\r\n          <div class=\"doer-details\">\r\n            <div class=\"detail-row\" *ngIf=\"doer.address\">\r\n              <ion-icon name=\"location-outline\"></ion-icon>\r\n              <a *ngIf=\"doer.addressLocation\" [href]=\"doer.addressLocation\" target=\"_blank\" class=\"loc-link\">{{ doer.address }}</a>\r\n              <span *ngIf=\"!doer.addressLocation\">{{ doer.address }}</span>\r\n            </div>\r\n\r\n            <div class=\"detail-row\" *ngIf=\"doer.phone\">\r\n              <ion-icon name=\"call-outline\"></ion-icon>\r\n              <a [href]=\"'tel:' + doer.phone\">{{ doer.phone }}</a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"faq-empty-state\" *ngIf=\"!isLoadingList && doers.length === 0\">\r\n        <div class=\"empty-icon\">📍</div>\r\n        <h3>مرکزی یافت نشد</h3>\r\n        <p>در حال حاضر مرکزی برای نمایش در این بخش ثبت نشده است.</p>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <app-footer></app-footer>\r\n</ion-content>\r\n\r\n";

